package worker

import (
	"encoding/json"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"sync"
)

type Result struct {
	Job   string
	Value int
}

const resultsPath = "out/results.json"

// RunAll processes jobs with two workers, then appends all results to out/results.json.
// Workers write only to their own slots in results; the file is written once, after they finish.
func RunAll(jobs []string) error {
	results := make([]Result, len(jobs))
	var wg sync.WaitGroup
	for w := 0; w < 2; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			for i := w; i < len(jobs); i += 2 {
				results[i] = Result{Job: jobs[i], Value: len(jobs[i])}
			}
		}(w)
	}
	wg.Wait()
	return appendResults(results)
}

func appendResults(rs []Result) error {
	var all []Result
	b, err := os.ReadFile(resultsPath)
	switch {
	case err == nil:
		if err := json.Unmarshal(b, &all); err != nil {
			return err
		}
	case !errors.Is(err, fs.ErrNotExist):
		return err
	}
	all = append(all, rs...)
	b, err = json.Marshal(all)
	if err != nil {
		return err
	}
	// Write to a temp file and rename so readers never see a partially written file.
	tmp, err := os.CreateTemp(filepath.Dir(resultsPath), ".results-*.json")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(b); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), resultsPath)
}
EOF
